"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { User, Calendar, Video, MessageCircle, Stethoscope, DollarSign, Star, Users, Clock } from "lucide-react";
import {Card} from "@/components/ui/card";
import { Avatar } from "@/components/ui/avatar";
import Badge from "@/components/ui/badge";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import Switch from "@/components/ui/switch";
import StatCard from "@/components/stat-card";
import AppointmentCard from "@/components/appointment-card";
import PatientCard from "@/components/patient-card";
import { Separator } from "@/components/separator";

export default function DashboardPage() {
  const [user, setUser] = useState(null);
  const [availability, setAvailability] = useState(true);
  const [search, setSearch] = useState("");
  const router = useRouter();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      router.push("/login");
      return;
    }
    try {
      const payload = JSON.parse(atob(token.split(".")[1]));
      setUser(payload);
    } catch {
      localStorage.removeItem("token");
      router.push("/login");
    }
  }, [router]);

  const handleLogout = () => {
    localStorage.removeItem("token");
    router.push("/login");
  };

  // Mock data
  const doctor = {
    name: user?.name || "Dr. Sharma",
    avatar: "/globe.svg",
    specialization: "Cardiologist",
  };
  const stats = [
    { label: "Consultations This Week", value: 18, icon: Stethoscope, progress: 72 },
    { label: "Monthly Earnings", value: "$4,200", icon: DollarSign },
    { label: "Avg. Rating", value: "4.8", icon: Star },
    { label: "New Patients", value: 6, icon: Users },
  ];
  const appointments = [
    {
      patientName: "Amit Verma",
      patientAvatar: "/file.svg",
      date: "Today",
      time: "10:00 AM",
      type: "Video",
      typeIcon: Video,
    },
    {
      patientName: "Priya Singh",
      patientAvatar: "/window.svg",
      date: "Today",
      time: "11:30 AM",
      type: "Chat",
      typeIcon: MessageCircle,
    },
    {
      patientName: "Rahul Mehra",
      patientAvatar: "/vercel.svg",
      date: "Tomorrow",
      time: "09:00 AM",
      type: "Video",
      typeIcon: Video,
    },
  ];
  const pastPatients = [
    { patientName: "Amit Verma", lastVisit: "2024-05-10", avatar: "/file.svg" },
    { patientName: "Priya Singh", lastVisit: "2024-05-02", avatar: "/window.svg" },
    { patientName: "Rahul Mehra", lastVisit: "2024-04-28", avatar: "/vercel.svg" },
  ];

  const filteredPatients = pastPatients.filter(p =>
    p.patientName.toLowerCase().includes(search.toLowerCase())
  );

  if (!user) return null;

  return (
    <div className="flex">
      <div className="flex-1  flex flex-col min-h-screen bg-gray-100">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 p-4 sm:p-6">
          {stats.map((stat, i) => (
            <StatCard key={i} {...stat} />
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 sm:gap-6 p-4 sm:p-6 flex-1">
          <div className="lg:col-span-2 flex flex-col gap-4">
            
            <div className="flex flex-col gap-3">
              {appointments.map((appt, i) => (
                <AppointmentCard key={i} {...appt} onStart={() => alert(`Start consultation with ${appt.patientName}`)} />
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-4 sm:gap-6 mt-14">
            <Card className="p-3 sm:p-4 flex flex-col gap-3">
              <div className="flex items-center gap-2 mb-2">
                <User className="w-5 h-5 text-blue-500" />
                <span className="font-semibold text-gray-700">Search Past Patients</span>
              </div>
              <div className="relative">
                <Input
                  placeholder="Search by name..."
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="pl-10"
                />
                <span className="absolute left-3 top-2.5 text-gray-400">
                  <Users className="w-4 h-4" />
                </span>
              </div>
              <div className="flex flex-col gap-2 mt-2 max-h-48 overflow-y-auto">
                {filteredPatients.length === 0 && (
                  <div className="text-xs text-gray-400">No patients found.</div>
                )}
                {filteredPatients.map((p, i) => (
                  <PatientCard key={i} {...p} onViewHistory={() => alert(`Viewing history for ${p.patientName}`)} />
                ))}
              </div>
            </Card>

            <Card className="p-3 sm:p-4 flex flex-col gap-3">
              <div className="flex items-center gap-2 mb-2">
                <Stethoscope className="w-5 h-5 text-blue-500" />
                <span className="font-semibold text-gray-700">Quick Actions</span>
              </div>
              <Button className="w-full" size="lg" onClick={() => alert("Write new prescription")}>+ Write New Prescription</Button>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
} 